function promptline(text){return `<div class="mission-row"><span class="micro">◉ &nbsp; LIVE MISSION FEED</span><span class="mini-progress">${String(state.step+1).padStart(2,'0')} / ${String(stepCounts[state.current]).padStart(2,'0')}</span></div><div class="prompt">${text}</div>`}
const objects=[['Iron nail','🔩',true],['Nickel coin','🪙',true],['Cobalt piece','🔷',true],['Copper wire','〰️',false],['Aluminum foil','▱',false],['Wood piece','🪵',false],['Gold ring','💍',false],['Glass','🔹',false]];
function levelOne(){const b=$('#body');b.innerHTML=`${promptline('Drag an object to the correct bay—or tap an object, then tap a bay. <strong>Three metals are magnetic.</strong>')}<div class="playfield"><div class="object-grid">${objects.map((o,i)=>`<button class="object-chip" draggable="true" data-item="${i}" aria-label="${o[0]}"><span class="object-emoji">${o[1]}</span><span class="object-name">${o[0]}</span></button>`).join('')}</div><div class="zone-row"><button class="drop-zone" data-zone="magnet"><span class="zone-count" id="magCount">0 / 3</span><strong>⊕</strong> MAGNET ZONE</button><button class="drop-zone reject" data-zone="reject"><span class="zone-count" id="rejCount">0 / 5</span><strong>×</strong> REJECT ZONE</button></div></div>${footer('Perfect sort required. Wrong drops cost one life; your object stays on the bench.')}`;
let selected=null;const chips=[...document.querySelectorAll('.object-chip')],zones=[...document.querySelectorAll('.drop-zone')];function choose(i){if(state.sorted.includes(i))return;selected=i;chips.forEach(c=>c.classList.toggle('selected',+c.dataset.item===i));zones.forEach(z=>z.classList.remove('chosen'));}
function sort(zone){if(selected===null){feedback('Select an object first, cadet.');return}const i=selected,correct=objects[i][2]?(zone==='magnet'):(zone==='reject');if(!correct){state.levelErrors++;lose('POLARITY ERROR. That material belongs in the other bay.');return}state.sorted.push(i);chips[i].classList.add('sorted');selected=null;$('#magCount').textContent=`${state.sorted.filter(x=>objects[x][2]).length} / 3`;$('#rejCount').textContent=`${state.sorted.filter(x=>!objects[x][2]).length} / 5`;chips.forEach(c=>c.classList.remove('selected'));if(state.sorted.length===objects.length){if(state.levelErrors===0){win(250,'Perfect sort! Iron, nickel, and cobalt are ferromagnetic; this set’s other materials are not.')}
else{state.sorted=[];setTimeout(()=>{if(state.lives>0){levelOne();feedback('Not a zero-error run—bench reset. Sort every item correctly to clear this trial.','bad')}},650)}}}
chips.forEach(c=>{c.onclick=()=>choose(+c.dataset.item);c.ondragstart=e=>{choose(+c.dataset.item);e.dataTransfer.setData('text/plain',c.dataset.item)};c.ondragend=()=>zones.forEach(z=>z.classList.remove('over'))});zones.forEach(z=>{z.onclick=()=>sort(z.dataset.zone);z.ondragover=e=>{e.preventDefault();z.classList.add('over')};z.ondragleave=()=>z.classList.remove('over');z.ondrop=e=>{e.preventDefault();z.classList.remove('over');const n=e.dataTransfer.getData('text/plain');if(n!=='')choose(+n);sort(z.dataset.zone)}})}
function optionGroup(items,onPick,selected=-1){return `<div class="option-grid">${items.map((t,i)=>`<button class="option ${selected===i?'selected':''}" data-opt="${i}"><span class="option-letter">${String.fromCharCode(65+i)}</span>${t}</button>`).join('')}</div>`}
function wireOptions(onPick){document.querySelectorAll('.option').forEach(o=>o.onclick=()=>{document.querySelectorAll('.option').forEach(x=>x.classList.remove('selected'));o.classList.add('selected');onPick(+o.dataset.opt)})}
function levelTwo(){const strongest=state.step===0;const b=$('#body'),question=strongest?'Tap the region where magnetic attraction is <strong>strongest</strong>.':'Now identify the region where magnetic attraction is <strong>weakest</strong>.';b.innerHTML=`${promptline(question)}<div class="playfield"><div class="diagram"><div class="magnet-lines"></div><div class="bar-magnet"><span class="magnet-label">N</span><span class="magnet-label">S</span></div><button class="option" id="polePick" style="position:absolute;left:8%;top:20%;width:30%;text-align:center">POLES</button><button class="option" id="middlePick" style="position:absolute;right:8%;bottom:13%;width:30%;text-align:center">MIDDLE</button></div><div class="fact-line">IRON FILINGS GATHER DENSELY WHERE THE FIELD IS STRONGEST</div></div>${footer('Field lines are closest together where the magnetic field is strongest.')}`;let pick=null;$('#polePick').onclick=()=>select(0);$('#middlePick').onclick=()=>select(1);function select(n){pick=n;$('#polePick').classList.toggle('selected',n===0);$('#middlePick').classList.toggle('selected',n===1);$('#actionBtn').disabled=false}$('#actionBtn').onclick=()=>{const good=strongest?pick===0:pick===1;if(!good){lose('Read the field density: the poles are strongest; the middle is weakest.');return}win(125,strongest?'Correct—the poles concentrate magnetic force, so iron filings cluster there.':'Correct—the field is weakest in the middle of this bar magnet.')};}

