const b=$('#body');b.innerHTML=`${promptline('Quick-fire: which <strong>geographical pole</strong> is near Earth’s magnetic south pole?')}<div class="playfield"><div class="fact-line">EARTH’S COMPASS-SEEKING NORTH END IS ATTRACTED TOWARD A MAGNETIC SOUTH POLE.<br>THE MAGNETIC AND GEOGRAPHIC POLES ARE NOT THE SAME THING.</div>${optionGroup(['Geographical North Pole','Geographical South Pole','The equator','There is no nearby geographical pole'])}</div>${footer('Remember: opposite magnetic poles attract.')}`;let pick=-1;wireOptions(n=>{pick=n;$('#actionBtn').disabled=false});$('#actionBtn').onclick=()=>{if(pick!==0){lose('Earth’s magnetic south pole lies near the geographical North Pole.');return}win(150,'Exactly. Earth’s magnetic south pole is near its geographical North Pole.')};}
