const b=$('#body');b.innerHTML=`${promptline('Which statement about magnetic field lines is <strong>always true</strong>?')}<div class="playfield"><div class="fact-line">FIELD LINES SHOW DIRECTION AND RELATIVE FIELD STRENGTH.<br>OUTSIDE A MAGNET, THEY RUN FROM NORTH TO SOUTH.</div>${optionGroup(['They cross wherever the field is strongest.','They never intersect; a compass gives the field direction at a point.','They start at S and end at N outside the magnet.','They are equally spaced everywhere.'])}</div>${footer('A single compass needle cannot point in two directions at once.')}`;let pick=-1;wireOptions(n=>{pick=n;$('#actionBtn').disabled=false});$('#actionBtn').onclick=()=>{if(pick!==1){lose('Field lines never cross; their tangent gives the field direction at each point.');return}win(150,'Correct. Non-intersecting field lines show a unique direction at every point.')};}

