 function renderGame(){shell();[levelOne,levelTwo,levelThree,levelFour,levelFive,levelSix,levelSeven][state.current]();}
 function feedback(text,kind=''){const el=$('#feedback');if(el){el.textContent=text;el.className=`feedback ${kind}`;}}
 function lose(msg){state.lives=Math.max(0,state.lives-1);state.wrong++;updateHud();const card=$('.playfield');if(card){card.classList.remove('sound');void card.offsetWidth;card.classList.add('sound')}feedback(msg,'bad');if(state.lives===0)setTimeout(gameOver,550);}
 function win(points=150,msg='Correct. Field data locked in.'){state.score+=points;state.step++;updateHud();feedback(msg,'good');setTimeout(()=>{if(state.step>=stepCounts[state.current])completeLevel();else renderGame()},700);}
-const stepCounts=[1,2,2,1,3,3,3];
+const stepCounts=[1,2,2,2,5,3,3];
 function completeLevel(){if(state.completed===state.current)state.completed++;state.unlocked=Math.max(state.unlocked,Math.min(6,state.current+1));state.score+=100;updateHud();if(state.current===6){showModal('✦','ALL SYSTEMS STABLE','FIELD MASTER','You cleared all seven trials and mastered magnetic materials, fields, poles, gravity, mass, weight, and orbital effects. Station saved. Final score: '+state.score,'PLAY AGAIN',()=>reset())}else showModal('✓',`TRIAL 0${state.current+1} COMPLETE`,'FIELD STABILIZED','+100 mission bonus. New sector unlocked. Keep your readings sharp, cadet.','NEXT TRIAL',()=>loadLevel(state.current+1));}
 function showModal(icon,eyebrow,title,text,button,action){$('#modalIcon').textContent=icon;$('#modalEyebrow').textContent=eyebrow;$('#modalTitle').textContent=title;$('#modalText').textContent=text;$('#modalBtn').textContent=button;$('#modalBtn').onclick=()=>{$('#overlay').classList.add('hidden');action()};$('#overlay').classList.remove('hidden')}
 function gameOver(){showModal('♥','SIMULATION PAUSED','OUT OF LIVES','Your readings drifted off course. The science is still there—reset your run and try again.','RESTART RUN',()=>reset())}
 function reset(){Object.assign(state,{score:0,lives:3,unlocked:0,current:0,completed:0,wrong:0,sorted:[],step:0,answers:[]});updateHud();loadLevel(0)}

