const sleep = ms => new Promise(r => setTimeout(r, ms));
const target = await (await fetch('http://localhost:9222/json/new?file:///home/runner/work/PlayGround/PlayGround/index.html', {method:'PUT'})).json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ ws.onopen=resolve; ws.onerror=reject; });
let id=0; const pending=new Map();
ws.onmessage=event=>{const m=JSON.parse(event.data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
async function evalPage(expression){const n=++id;const result=new Promise(resolve=>pending.set(n,resolve));ws.send(JSON.stringify({id:n,method:'Runtime.evaluate',params:{expression,awaitPromise:true,returnByValue:true}}));const m=await result;if(m.result?.exceptionDetails) throw new Error(m.result.exceptionDetails.text);return m.result?.result?.value}
async function run(expr){return evalPage(`(async()=>{${expr}})()`)}
try {
 console.log('initial', await evalPage(`({title:document.title, level:document.querySelector('h2')?.textContent, chips:document.querySelectorAll('.object-chip').length, screenshotWidth:innerWidth})`));
 console.log('level1', await run(`for(let i=0;i<8;i++){document.querySelector('[data-item="'+i+'"]').click();document.querySelector('[data-zone="'+(i<3?'magnet':'reject')+'"]').click()} await new Promise(r=>setTimeout(r,800)); return {modal:!document.querySelector('#overlay').classList.contains('hidden'), feedback:document.querySelector('#feedback')?.textContent, sorted:window.state?.sorted?.length, completed:document.querySelector('#progressText').textContent}`));
