 console.log('level2', await run(`document.querySelector('#polePick').click();document.querySelector('#actionBtn').click();await new Promise(r=>setTimeout(r,800));document.querySelector('#middlePick').click();document.querySelector('#actionBtn').click();await new Promise(r=>setTimeout(r,800)); return {modal:!document.querySelector('#overlay').classList.contains('hidden'),level:document.querySelector('h2').textContent}`));
 await evalPage(`document.querySelector('#modalBtn').click()`);
 console.log('level3 compass', await run(`for(let i=0;i<6;i++)document.querySelector('#rotate').click();return {rotation:document.querySelector('#needle').style.transform,angle:document.querySelector('#angleRead').textContent};`));
 await evalPage(`document.querySelector('#actionBtn').click()`); await sleep(800);
 console.log('level3 earth',await run(`document.querySelectorAll('.option')[0].click();document.querySelector('#actionBtn').click();await new Promise(r=>setTimeout(r,800));return {modal:!document.querySelector('#overlay').classList.contains('hidden'),level:document.querySelector('h2').textContent}`));
 await evalPage(`document.querySelector('#modalBtn').click()`);
 console.log('level4 polarity', await run(`for(const [i,v] of ['S','N','S'].entries())document.querySelector('[data-ring="'+i+'"]').value=v;document.querySelector('#actionBtn').click();await new Promise(r=>setTimeout(r,800));return {feedback:document.querySelector('#feedback')?.textContent,modal:!document.querySelector('#overlay').classList.contains('hidden'),lives:document.querySelector('#lives').textContent}`));
} finally { ws.close(); }

